 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY step_id),'[]'::jsonb) INTO effects_value FROM zasp_temporal68.effects x WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
