,false) OR NOT COALESCE((zasp_temporal68.principal_ready('zasp_temporal_executor') OR op='stop' AND zasp_temporal68.principal_ready('zasp_temporal_compensation')),false)
  OR op NOT IN('progress','stop') AND (fresh<clock_timestamp()-interval '5 minutes' OR fresh>clock_timestamp()+interval '5 seconds')
